const normalized=value=>String(value).replace(/\s+/g,' ').trim();
export function t(text,values={}){const key=normalized(text);const translated=language==='en'?text:dictionaries[language]?.[key]??text;return String(translated).replace(/\{(\w+)\}/g,(match,key)=>Object.hasOwn(values,key)?String(values[key]):match);}
export function translateText(text){
 if(language==='en')return String(text);
 const source=normalized(text),exact=dictionaries[language]?.[source];if(exact)return exact;
 let result=String(text);
 const savedAction=source.match(/^(Restore|Delete|Contact) (.+)$/);if(savedAction)return t(savedAction[1])+' '+savedAction[2];
 const contactLabel=source.match(/^(WhatsApp|Viber|Call) (Irina|Constantin) at (.+)$/);if(contactLabel)return t(contactLabel[1])+': '+contactLabel[2]+' · '+contactLabel[3];
 const validation=source.match(/^(.+) must be (a whole number )?between (.+) and (.+)\.$/);
 if(validation)return t(validation[2]?'validation.integer':'validation.number',{field:translateText(validation[1]),min:validation[3],max:validation[4]});
 for(const prefix of Object.keys({Maintenance:1,Renovation:1,Cleaning:1,'Contract repairs':1,Landscaping:1,Management:1})){if(source.startsWith(prefix+' ')){const rest=source.slice(prefix.length+1);const translatedRest=dictionaries[language]?.[rest]??dictionaries[language]?.[rest[0].toUpperCase()+rest.slice(1)];if(translatedRest)return t(prefix)+' '+translatedRest;}}
 const tokenKeys=['Residential','Commercial','residential','commercial','Cyprus','Nicosia','Limassol','Larnaca','Paphos','Famagusta district','Other location in Cyprus','weekly · monthly average','visits / month','1 visit / month','2 visits / month','one-off','monthly','per month','selected','services','incl. VAT','hours','hour','hrs','visits','visit','units','unit','on-site work'];
 for(const key of tokenKeys){const escaped=key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');result=result.replace(new RegExp(`(?<![A-Za-z])${escaped}(?![A-Za-z])`,'g'),()=>t(key));}
 for(const key of [' / month',' / mo',' / visit',' · minimum ',' applied',' · condition × ',' travel'])result=result.split(key).join(t(key));
 return result;
}
export const translateBlock=value=>String(value).split('\n').map(translateText).join('\n');
export function setLanguage(next){if(!languageLocales[next])return;language=next;if(typeof document==='undefined')return;try{localStorage.setItem('inonda-language',language);}catch{}const url=new URL(location.href);if(language==='el')url.searchParams.delete('lang');else url.searchParams.set('lang',language);history.replaceState(null,'',url);document.documentElement.lang=language;document.documentElement.dir=language==='he'?'rtl':'ltr';document.querySelector('#language').value=language;document.querySelector('#language').setAttribute('aria-label',t('Language'));document.querySelector('link[rel="canonical"]').href=`https://www.inonda.homes/${language==='el'?'':`?lang=${language}`}`;document.title=t('Service Estimator · INONDA LTD');document.querySelector('meta[name=description]').content=t('Explore your property plan with INONDA LTD. Build your own estimate in Cyprus, with 19% VAT included, then call to arrange an inspection and written offer.');document.dispatchEvent(new CustomEvent('inonda:language'));localizeDocument();}
const originals=new WeakMap(),originalAttributes=new WeakMap();
export function localizeDocument(){if(typeof document==='undefined')return;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const node of nodes){if(node.parentElement?.closest('script,style,textarea,noscript,[data-no-i18n]'))continue;if(!originals.has(node))originals.set(node,node.data);const source=originals.get(node),prefix=source.match(/^\s*/)[0],suffix=source.match(/\s*$/)[0],next=source.trim()?prefix+translateText(source.trim())+suffix:source;if(node.data!==next)node.data=next;}for(const el of document.querySelectorAll('[aria-label],[placeholder],[title],[alt]')){if(el.closest('[data-no-i18n]'))continue;let originalsForElement=originalAttributes.get(el);if(!originalsForElement){originalsForElement={};originalAttributes.set(el,originalsForElement);}for(const attribute of ['aria-label','placeholder','title','alt'])if(el.hasAttribute(attribute)){if(!(attribute in originalsForElement))originalsForElement[attribute]=el.getAttribute(attribute);const next=translateText(originalsForElement[attribute]);if(el.getAttribute(attribute)!==next)el.setAttribute(attribute,next);}}const vat=document.querySelector('#vat-display');if(vat)vat.value='19%';}
export function initI18n(){document.querySelectorAll('select option').forEach(option=>{if(!option.hasAttribute('value'))option.value=option.textContent;});document.querySelector('#language').addEventListener('change',event=>setLanguage(event.target.value));document.querySelector('.inonda-language-bar')?.addEventListener('click',event=>{const link=event.target.closest('a[data-golang]');if(!link||event.button!==0||event.metaKey||event.ctrlKey||event.shiftKey||event.altKey)return;event.preventDefault();setLanguage(link.dataset.golang);});setLanguage(language);new MutationObserver(()=>localizeDocument()).observe(document.body,{childList:true,subtree:true});}
export const translationDictionary=lang=>({...dictionaries[lang]});
const details=[
['Service Estimator · INONDA LTD','Εκτιμητής Υπηρεσιών · INONDA LTD','Калькулятор услуг · INONDA LTD','Калькулятор послуг · INONDA LTD','מחשבון שירותים · INONDA LTD','Estimator de servicii · INONDA LTD'],
['Base assumptions:','Βασικές παραδοχές:','Базовые допущения:','Базові припущення:','הנחות בסיס:','Ipoteze de bază:'],
['Cleaning & gardening:','Καθαρισμός και κηποτεχνία:','Уборка и сад:','Прибирання та сад:','ניקיון וגינון:','Curățenie și grădinărit:'],
['Renovation:','Ανακαίνιση:','Ремонт:','Ремонт:','שיפוץ:','Renovare:'],
['Maintenance & contract repairs:','Συντήρηση και μικροεπισκευές:','Обслуживание и мелкий ремонт:','Обслуговування й дрібний ремонт:','תחזוקה ותיקונים קטנים:','Întreținere și reparații mici:'],
['accessible property, normal working hours and the selected scope only. Rates, minimums and condition adjustments are prototype assumptions, not verified Cyprus market prices or approved INONDA tariffs. Displayed rates reflect the selected property type and include 19% VAT.','Προσβάσιμο ακίνητο, κανονικό ωράριο και μόνο το επιλεγμένο αντικείμενο. Οι τιμές, τα ελάχιστα και οι προσαρμογές κατάστασης είναι ενδεικτικές παραδοχές του πρωτοτύπου, όχι επαληθευμένες τιμές αγοράς Κύπρου ή εγκεκριμένοι τιμοκατάλογοι INONDA. Οι εμφανιζόμενες τιμές αντιστοιχούν στον επιλεγμένο τύπο ακινήτου και περιλαμβάνουν 19% ΦΠΑ.','Доступный объект, обычные рабочие часы и только выбранные работы. Цены, минимумы и поправки ориентировочные: это не проверенные рыночные цены Кипра и не утверждённые тарифы INONDA. Показаны цены для выбранного типа объекта с НДС 19%.','Доступний об’єкт, звичайні робочі години й лише обрані роботи. Ціни, мінімуми та поправки орієнтовні: це не перевірені ринкові ціни Кіпру й не затверджені тарифи INONDA. Показано ціни для обраного типу об’єкта з ПДВ 19%.','נכס נגיש, שעות עבודה רגילות וההיקף שנבחר בלבד. התעריפים, המינימום וההתאמות הם הנחות להמחשה, לא מחירי שוק מאומתים בקפריסין או מחירון מאושר של INONDA. המחירים מתאימים לסוג הנכס שנבחר וכוללים מע״מ 19%.','Proprietate accesibilă, program normal și doar lucrările selectate. Tarifele, minimele și ajustările sunt ipoteze orientative, nu prețuri de piață verificate în Cipru sau tarife INONDA aprobate. Prețurile corespund tipului selectat și includ TVA 19%.'],
['routine labour and basic consumables assumed; specialist machinery, waste removal, tall trees and hazardous materials excluded. Cleaning area is capped to indoor size.','Προβλέπονται συνήθης εργασία και βασικά αναλώσιμα. Εξαιρούνται ειδικός εξοπλισμός, απομάκρυνση αποβλήτων, ψηλά δέντρα και επικίνδυνα υλικά. Η επιφάνεια καθαρισμού δεν υπερβαίνει το εσωτερικό εμβαδόν.','Учтены обычные работы и базовые расходники. Спецтехника, вывоз отходов, высокие деревья и опасные материалы исключены. Площадь уборки не превышает площадь помещений.','Враховано звичайні роботи та базові витратні матеріали. Спецтехніку, вивезення відходів, високі дерева й небезпечні матеріали виключено. Площа прибирання не перевищує площу приміщень.','כלולים עבודה שוטפת וחומרים מתכלים בסיסיים. ציוד מיוחד, פינוי פסולת, עצים גבוהים וחומרים מסוכנים אינם כלולים. שטח הניקיון מוגבל לשטח הפנימי.','Sunt incluse manopera obișnuită și consumabilele de bază. Nu sunt incluse utilajele speciale, evacuarea deșeurilor, arborii înalți sau materialele periculoase. Curățenia este limitată la suprafața interioară.'],
['the selected finish allowance and labour only. Structural changes, permits, surveys, major plumbing/electrical works, fixtures and unforeseen defects are excluded. A site survey and licensed professionals may be required.','Μόνο η επιλεγμένη πρόβλεψη τελειωμάτων και η εργασία. Εξαιρούνται δομικές αλλαγές, άδειες, μελέτες, μεγάλα υδραυλικά/ηλεκτρολογικά έργα, εξαρτήματα και απρόβλεπτα ελαττώματα. Μπορεί να απαιτούνται επιτόπιος έλεγχος και αδειούχοι επαγγελματίες.','Только выбранная отделка и работа. Перепланировка конструкций, разрешения, обследования, крупные сантехнические и электрические работы, оборудование и скрытые дефекты исключены. Возможны обследование и участие лицензированных специалистов.','Лише обране оздоблення та робота. Зміни конструкцій, дозволи, обстеження, великі сантехнічні й електричні роботи, обладнання та приховані дефекти виключено. Можуть знадобитися обстеження та ліцензовані фахівці.','רק אומדן הגמר והעבודה שנבחרו. שינויים מבניים, היתרים, סקרים, עבודות אינסטלציה וחשמל גדולות, אביזרים וליקויים נסתרים אינם כלולים. ייתכן שיידרשו סקר ובעלי מקצוע מורשים.','Doar finisajele selectate și manopera. Nu sunt incluse modificările structurale, autorizațiile, expertizele, lucrările majore de instalații sau electricitate, dotările și defectele neprevăzute. Pot fi necesare o evaluare la fața locului și specialiști autorizați.'],
['inspection or labour allowance only; parts, repairs and specialist trades excluded. Management covers coordination and reporting only; third-party bills and rent collection are excluded.','Μόνο πρόβλεψη επιθεώρησης ή εργασίας. Εξαιρούνται ανταλλακτικά, επισκευές και εξειδικευμένα επαγγέλματα. Η διαχείριση καλύπτει μόνο συντονισμό και αναφορές· εξαιρούνται λογαριασμοί τρίτων και είσπραξη ενοικίων.','Только осмотр или труд. Детали, ремонт и специальные работы исключены. Управление включает только координацию и отчётность, без счетов третьих лиц и сбора аренды.','Лише огляд або праця. Деталі, ремонт і спеціальні роботи виключено. Управління включає лише координацію та звітність, без рахунків третіх осіб і збору орендної плати.','אומדן לבדיקה או לעבודה בלבד. חלקים, תיקונים ועבודות מומחים אינם כלולים. הניהול כולל תיאום ודיווח בלבד, ללא חשבונות צד שלישי וגביית שכירות.','Doar inspecția sau manopera. Piesele, reparațiile și lucrările specializate sunt excluse. Administrarea acoperă doar coordonarea și raportarea, fără facturi ale terților sau colectarea chiriei.'],
['Monthly cleaning or gardening uses the selected visit frequency. Weekly visits average 52 ÷ 12 per month. Monthly figures are ongoing costs; one-off work is separate. No duration or availability is promised.','Ο μηνιαίος καθαρισμός ή η κηποτεχνία χρησιμοποιεί την επιλεγμένη συχνότητα. Οι εβδομαδιαίες επισκέψεις υπολογίζονται κατά μέσο όρο ως 52 ÷ 12 τον μήνα. Τα μηνιαία ποσά είναι συνεχή κόστη· οι εφάπαξ εργασίες είναι ξεχωριστές. Δεν παρέχεται υπόσχεση διάρκειας ή διαθεσιμότητας.','Месячная уборка и садовые работы учитывают выбранную частоту. Еженедельные визиты в среднем равны 52 ÷ 12 в месяц. Постоянные и разовые расходы показаны отдельно. Сроки и доступность не обещаются.','Місячне прибирання й садові роботи враховують обрану частоту. Щотижневі візити в середньому дорівнюють 52 ÷ 12 на місяць. Постійні й разові витрати показано окремо. Строки та доступність не обіцяються.','ניקיון או גינון חודשי משתמשים בתדירות שנבחרה. ביקורים שבועיים מחושבים בממוצע 52 ÷ 12 לחודש. עלויות חודשיות הן שוטפות; עבודה חד פעמית נפרדת. אין התחייבות למשך או לזמינות.','Curățenia și grădinăritul lunar folosesc frecvența selectată. Vizitele săptămânale sunt calculate în medie ca 52 ÷ 12 pe lună. Costurile recurente și lucrările unice sunt separate. Nu se promit durată sau disponibilitate.'],
['Preventive inspection; repairs and parts excluded.','Προληπτική επιθεώρηση· εξαιρούνται επισκευές και ανταλλακτικά.','Профилактический осмотр; ремонт и детали исключены.','Профілактичний огляд; ремонт і деталі виключено.','בדיקה מונעת; תיקונים וחלקים אינם כלולים.','Inspecție preventivă; reparațiile și piesele sunt excluse.'],
['Cosmetic refresh; labour and basic finish allowance only.','Αισθητική ανανέωση· μόνο εργασία και βασικά τελειώματα.','Косметическое обновление; только работа и базовая отделка.','Косметичне оновлення; лише робота й базове оздоблення.','רענון קוסמטי; עבודה וגמרים בסיסיים בלבד.','Reîmprospătare cosmetică; doar manoperă și finisaje de bază.'],
['Deep clean of the selected indoor area.','Βαθύς καθαρισμός της επιλεγμένης εσωτερικής επιφάνειας.','Генеральная уборка выбранной площади помещений.','Генеральне прибирання обраної площі приміщень.','ניקיון יסודי של השטח הפנימי שנבחר.','Curățenie generală a suprafeței interioare selectate.'],
['Small-repair labour for maintenance-contract customers; materials and specialist trades excluded.','Γενική εργασία μικροεπισκευών· εξαιρούνται υλικά και εξειδικευμένα επαγγέλματα.','Общие работы мастера; материалы и специальные работы исключены.','Загальні роботи майстра; матеріали й спеціальні роботи виключено.','עבודות תיקונים כלליות; חומרים ועבודות מומחים אינם כלולים.','Manoperă pentru reparații mici; materialele și specialiștii sunt excluși.'],
['Routine garden tidy; landscaping construction and waste removal excluded.','Τακτική περιποίηση κήπου· εξαιρούνται κατασκευές κήπου και απομάκρυνση αποβλήτων.','Обычный уход за садом; строительство и вывоз отходов исключены.','Звичайний догляд за садом; будівництво й вивезення відходів виключено.','סידור גינה שוטף; בניית גן ופינוי פסולת אינם כלולים.','Îngrijire obișnuită a grădinii; construcțiile și evacuarea deșeurilor sunt excluse.'],
['Monthly service coordination and reporting; third-party bills excluded.','Μηνιαίος συντονισμός υπηρεσιών και αναφορές· εξαιρούνται λογαριασμοί τρίτων.','Ежемесячная координация и отчётность; счета третьих лиц исключены.','Щомісячна координація та звітність; рахунки третіх осіб виключено.','תיאום ודיווח שירותים חודשי; חשבונות צד שלישי אינם כלולים.','Coordonare și raportare lunară; facturile terților sunt excluse.'],
['Routine clean of the selected indoor area.','Τακτικός καθαρισμός της επιλεγμένης εσωτερικής επιφάνειας.','Регулярная уборка выбранной площади помещений.','Регулярне прибирання обраної площі приміщень.','ניקיון שוטף של השטח הפנימי שנבחר.','Curățenie periodică a suprafeței interioare selectate.'],
['Move-in / move-out clean of the selected indoor area; property assumed empty.','Καθαρισμός εισόδου / αποχώρησης της επιλεγμένης επιφάνειας· θεωρείται κενό ακίνητο.','Уборка при въезде / выезде выбранных помещений; объект считается пустым.','Прибирання при заселенні / виїзді обраних приміщень; об’єкт вважається порожнім.','ניקיון לפני כניסה או לאחר עזיבה; הנכס נחשב ריק.','Curățenie la mutare sau eliberare; proprietatea este considerată goală.'],
['Cosmetic paint and minor finish refresh; labour and basic finish allowance only.','Αισθητικό βάψιμο και μικρή ανανέωση τελειωμάτων· μόνο εργασία και βασικά τελειώματα.','Косметическая покраска и небольшое обновление; только работа и базовая отделка.','Косметичне фарбування й невелике оновлення; лише робота й базове оздоблення.','צביעה קוסמטית ורענון גמרים קל; עבודה וגמרים בסיסיים בלבד.','Vopsire cosmetică și reîmprospătare minoră; doar manoperă și finisaje de bază.'],
['Selected room finishes and minor refurbishment; major plumbing/electrical works and fixtures excluded.','Τελειώματα επιλεγμένων δωματίων και μικρή ανακαίνιση· εξαιρούνται μεγάλα υδραυλικά/ηλεκτρολογικά έργα και εξαρτήματα.','Отделка выбранных комнат и небольшой ремонт; крупные инженерные работы и оборудование исключены.','Оздоблення обраних кімнат і невеликий ремонт; великі інженерні роботи й обладнання виключено.','גמרים לחדרים נבחרים ושיפוץ קל; עבודות אינסטלציה וחשמל גדולות ואביזרים אינם כלולים.','Finisaje în camere selectate și renovări minore; instalațiile majore, electricitatea și dotările sunt excluse.'],
['Broad internal finish refurbishment; structural works, permits, major services and fixtures excluded.','Εκτεταμένη εσωτερική ανακαίνιση τελειωμάτων· εξαιρούνται δομικά έργα, άδειες, μεγάλες εγκαταστάσεις και εξαρτήματα.','Полное обновление внутренней отделки; конструкции, разрешения, крупные инженерные системы и оборудование исключены.','Повне оновлення внутрішнього оздоблення; конструкції, дозволи, великі інженерні системи й обладнання виключено.','חידוש נרחב של גמרי הפנים; מבנה, היתרים, מערכות גדולות ואביזרים אינם כלולים.','Renovare amplă a finisajelor interioare; structura, autorizațiile, instalațiile majore și dotările sunt excluse.'],
['A little planning goes a long way.','Λίγος σχεδιασμός κάνει τη διαφορά.','Немного планирования — большая польза.','Трохи планування — велика користь.','תכנון קטן עושה הבדל גדול.','Puțină planificare face diferența.'],
['Start with your property.','Ξεκινήστε με το ακίνητό σας.','Начните с объекта.','Почніть з об’єкта.','התחילו בנכס שלכם.','Începe cu proprietatea.'],
['Choose a type, location, indoor size and condition.','Επιλέξτε τύπο, τοποθεσία, εσωτερικό εμβαδόν και κατάσταση.','Выберите тип, место, площадь и состояние.','Оберіть тип, місце, площу та стан.','בחרו סוג, מיקום, שטח פנימי ומצב.','Alege tipul, localitatea, suprafața și starea.'],
['Build your scope.','Διαμορφώστε το αντικείμενο.','Составьте объём работ.','Складіть обсяг робіт.','בנו את ההיקף.','Stabilește lucrările.'],
['Select services and adjust area, hours, frequency, minimums and rates.','Επιλέξτε υπηρεσίες και ρυθμίστε εμβαδόν, ώρες, συχνότητα, ελάχιστα και τιμές.','Выберите услуги и задайте площадь, часы, частоту, минимумы и цены.','Оберіть послуги й задайте площу, години, частоту, мінімуми та ціни.','בחרו שירותים והתאימו שטח, שעות, תדירות, מינימום ותעריפים.','Alege serviciile și ajustează suprafața, orele, frecvența, minimele și tarifele.'],
['Explore the budget.','Εξερευνήστε τον προϋπολογισμό.','Изучите бюджет.','Перегляньте бюджет.','בדקו את התקציב.','Explorează bugetul.'],
['Compare one-off and monthly costs, including 19% VAT and any reserve you set.','Συγκρίνετε εφάπαξ και μηνιαία κόστη, με 19% ΦΠΑ και το αποθεματικό που ορίζετε.','Сравните разовые и месячные расходы с НДС 19% и вашим резервом.','Порівняйте разові й місячні витрати з ПДВ 19% та вашим резервом.','השוו עלויות חד פעמיות וחודשיות, כולל מע״מ 19% וכל עתודה שהגדרתם.','Compară costurile unice și lunare, cu TVA 19% și rezerva stabilită.'],
['Take your plan with you.','Πάρτε το σχέδιό σας μαζί.','Сохраните план.','Збережіть план.','קחו את התוכנית איתכם.','Ia planul cu tine.'],
['Save locally, download the full assumptions or print a brief.','Αποθηκεύστε τοπικά, κατεβάστε τις παραδοχές ή εκτυπώστε το πλάνο.','Сохраните в браузере, скачайте допущения или распечатайте план.','Збережіть у браузері, завантажте припущення або роздрукуйте план.','שמרו מקומית, הורידו את ההנחות המלאות או הדפיסו תקציר.','Salvează local, descarcă ipotezele complete sau tipărește planul.'],
['All starting rates are illustrative and include 19% VAT. There is no booking, payment or quote submission in this prototype. Saved scenarios stay in this browser and do not sync between devices.','Όλες οι αρχικές τιμές είναι ενδεικτικές και περιλαμβάνουν 19% ΦΠΑ. Το πρωτότυπο δεν πραγματοποιεί κρατήσεις, πληρωμές ή αποστολές προσφορών. Τα σενάρια παραμένουν σε αυτόν τον φυλλομετρητή και δεν συγχρονίζονται μεταξύ συσκευών.','Исходные цены ориентировочные и включают НДС 19%. Прототип не оформляет записи, платежи или заявки на цену. Варианты хранятся в этом браузере без синхронизации устройств.','Початкові ціни орієнтовні й включають ПДВ 19%. Прототип не оформлює записи, платежі чи заявки на ціну. Варіанти зберігаються в цьому браузері без синхронізації пристроїв.','התעריפים ההתחלתיים להמחשה וכוללים מע״מ 19%. אב הטיפוס אינו מבצע הזמנות, תשלומים או שליחת בקשות להצעת מחיר. התרחישים נשמרים בדפדפן זה ואינם מסונכרנים בין מכשירים.','Tarifele inițiale sunt orientative și includ TVA 19%. Prototipul nu face programări, plăți sau trimiteri de oferte. Scenariile rămân în acest browser și nu se sincronizează între dispozitive.'],
['Your browser does not support video.','Ο φυλλομετρητής σας δεν υποστηρίζει βίντεο.','Ваш браузер не поддерживает видео.','Ваш браузер не підтримує відео.','הדפדפן אינו תומך בווידאו.','Browserul tău nu acceptă video.'],
['Watch the INONDA presentation','Δείτε την παρουσίαση INONDA','Смотреть презентацию INONDA','Дивитися презентацію INONDA','צפייה במצגת INONDA','Vezi prezentarea INONDA'],
["Text version of this video", "Κείμενο του βίντεο", "Текстовая версия видео", "Текстова версія відео", "גרסת טקסט של הסרטון", "Versiunea text a videoclipului"],
["The video has no speech; the soundtrack is instrumental music. It shows Inonda LTD technicians at work on homes in Cyprus, with these on-screen titles:", "Το βίντεο δεν έχει ομιλία· η μουσική υπόκρουση είναι ορχηστρική. Δείχνει τεχνικούς της Inonda LTD να εργάζονται σε σπίτια στην Κύπρο, με τους εξής τίτλους στην οθόνη:", "В видео нет речи, звучит инструментальная музыка. В нём показаны специалисты Inonda LTD за работой в домах на Кипре, с такими надписями на экране:", "У відео немає мовлення, звучить інструментальна музика. У ньому показано фахівців Inonda LTD за роботою в будинках на Кіпрі, з такими написами на екрані:", "בסרטון אין דיבור; פס הקול הוא מוזיקה אינסטרומנטלית. הוא מציג את טכנאי Inonda LTD בעבודה בבתים בקפריסין, עם הכותרות הבאות על המסך:", "Videoclipul nu conține vorbire; coloana sonoră este muzică instrumentală. Arată tehnicienii Inonda LTD lucrând în locuințe din Cipru, cu următoarele titluri pe ecran:"],
["Accessibility statement", "Δήλωση προσβασιμότητας", "Заявление о доступности", "Заява про доступність", "הצהרת נגישות", "Declarație de accesibilitate"],
["Inonda LTD — Maintain · Repair · Transform.", "Inonda LTD — Συντήρηση · Επισκευές · Ανακαίνιση.", "Inonda LTD — Обслуживание · Ремонт · Преображение.", "Inonda LTD — Обслуговування · Ремонт · Перетворення.", "Inonda LTD — תחזוקה · תיקונים · שיפוץ.", "Inonda LTD — Întreținere · Reparații · Transformare."],
["One contractor for everything — Nicosia and all of Cyprus.", "Ένας εργολάβος για όλα — Λευκωσία και όλη η Κύπρος.", "Один подрядчик для всего — Никосия и весь Кипр.", "Один підрядник для всього — Нікосія та весь Кіпр.", "קבלן אחד לכל העבודות — ניקוסיה וכל קפריסין.", "Un singur antreprenor pentru tot — Nicosia și tot Ciprul."],
["Written quotes, workmanship warranty — licensed technicians.", "Γραπτές προσφορές, εγγύηση — αδειούχοι τεχνικοί.", "Письменные сметы, гарантия на работы — лицензированные специалисты.", "Письмові кошториси, гарантія на роботи — ліцензовані фахівці.", "הצעות מחיר בכתב, אחריות על העבודה — טכנאים מורשים.", "Oferte scrise, garanție pentru manoperă — tehnicieni autorizați."],
["01/03 Maintenance: maintenance plans; scheduled checks and servicing; air conditioning: install, service, repair; roof waterproofing; stop leaks, damp and mould.", "01/03 Συντήρηση: προγράμματα συντήρησης· τακτικός έλεγχος και σέρβις· κλιματισμός: εγκατάσταση, σέρβις, επισκευή· στεγάνωση ταράτσας· τέλος στις διαρροές και την υγρασία.", "01/03 Обслуживание: планы обслуживания; плановые проверки и сервис; кондиционеры: установка, обслуживание, ремонт; гидроизоляция кровли; устранение протечек, сырости и плесени.", "01/03 Обслуговування: плани обслуговування; планові перевірки та сервіс; кондиціонери: встановлення, обслуговування, ремонт; гідроізоляція покрівлі; усунення протікань, вологи та цвілі.", "01/03 תחזוקה: תוכניות תחזוקה; בדיקות ושירות תקופתיים; מיזוג אוויר: התקנה, שירות ותיקון; איטום גגות; סוף לנזילות, לרטיבות ולעובש.", "01/03 Întreținere: planuri de întreținere; verificări și service periodic; aer condiționat: montaj, service, reparații; hidroizolarea acoperișului; gata cu scurgerile, umezeala și mucegaiul."],
["02/03 Repairs: plumbing; licensed plumbers; leaks, blockages, water heaters; electrical works; sockets, panels, lighting; urgent repairs, made safe fast.", "02/03 Επισκευές: υδραυλικά· αδειούχοι υδραυλικοί· διαρροές, βουλώματα, θερμοσίφωνες· ηλεκτρολογικά· πρίζες, πίνακες, φωτισμός· επείγουσες επισκευές.", "02/03 Ремонт: сантехника; лицензированные сантехники; протечки, засоры, водонагреватели; электромонтажные работы; розетки, щиты, освещение; срочный ремонт, быстро и безопасно.", "02/03 Ремонт: сантехніка; ліцензовані сантехніки; протікання, засмічення, водонагрівачі; електромонтажні роботи; розетки, щитки, освітлення; терміновий ремонт, швидко й безпечно.", "02/03 תיקונים: אינסטלציה; אינסטלטורים מורשים; נזילות, סתימות, דודי מים; עבודות חשמל; שקעים, לוחות חשמל, תאורה; תיקונים דחופים, בטוח ומהר.", "02/03 Reparații: instalații sanitare; instalatori autorizați; scurgeri, înfundări, boilere; lucrări electrice; prize, tablouri, iluminat; reparații urgente, rapid și în siguranță."],
["03/03 Home transformation: complete home renovation; new layouts; planning and itemised budget; kitchen renovation; modern living spaces; bathroom renovation; walk-in showers, full waterproofing; painting, plaster and gypsum; flooring and tiling; finishes that last; doors, windows and carpentry; made to measure; wardrobes and built-ins; outdoor works; pergolas, terraces and pool areas.", "03/03 Ανακαίνιση: ολική ανακαίνιση· νέες διαρρυθμίσεις· σχεδιασμός και προϋπολογισμός· ανακαίνιση κουζίνας· σύγχρονοι χώροι· ανακαίνιση μπάνιου· ντουζιέρες δαπέδου, πλήρης στεγάνωση· βαφές και γυψοσανίδες· δάπεδα και πλακάκια· φινιρίσματα που κρατούν· κουφώματα και ξυλουργικά· κατά παραγγελία· ντουλάπες και εντοιχισμένα· εξωτερικοί χώροι· πέργκολες, βεράντες, πισίνα.", "03/03 Преображение дома: капитальный ремонт дома; новые планировки; проектирование и подробная смета; ремонт кухни; современные пространства; ремонт ванной; душевые без поддона, полная гидроизоляция; покраска, штукатурка и гипсокартон; полы и плитка; долговечная отделка; двери, окна и столярные работы; на заказ; шкафы и встроенная мебель; работы на участке; перголы, террасы и зоны у бассейна.", "03/03 Перетворення дому: капітальний ремонт будинку; нові планування; проєктування та детальний кошторис; ремонт кухні; сучасні простори; ремонт ванної; душові без піддону, повна гідроізоляція; фарбування, штукатурка та гіпсокартон; підлоги та плитка; довговічне оздоблення; двері, вікна та столярні роботи; на замовлення; шафи та вбудовані меблі; роботи на ділянці; перголи, тераси та зони біля басейну.", "03/03 שיפוץ הבית: שיפוץ מלא של הבית; חלוקות חדשות; תכנון ותקציב מפורט; שיפוץ מטבח; חללי מגורים מודרניים; שיפוץ חדר רחצה; מקלחונים בגובה הרצפה, איטום מלא; צבע, טיח וגבס; ריצוף ואריחים; גימורים שמחזיקים; דלתות, חלונות ונגרות; בהתאמה אישית; ארונות ונישות מובנות; עבודות חוץ; פרגולות, מרפסות ואזורי בריכה.", "03/03 Transformarea locuinței: renovare completă; compartimentări noi; proiectare și buget detaliat; renovare bucătărie; spații moderne; renovare baie; dușuri walk-in, hidroizolare completă; zugrăveli, tencuieli și gips-carton; pardoseli și faianță; finisaje durabile; uși, ferestre și tâmplărie; la comandă; dulapuri și mobilier încastrat; amenajări exterioare; pergole, terase și zone de piscină."],
["How we work, in 5 steps: 1. Tell us what you need. 2. Site visit and assessment. 3. Written, itemised quote. 4. Work done right. 5. Handover and warranty.", "Πώς δουλεύουμε, σε 5 βήματα: 1. Πείτε μας τι χρειάζεστε. 2. Αυτοψία και εκτίμηση. 3. Γραπτή, αναλυτική προσφορά. 4. Σωστή εκτέλεση. 5. Παράδοση και εγγύηση.", "Как мы работаем, в 5 шагов: 1. Расскажите, что вам нужно. 2. Выезд и оценка. 3. Письменная подробная смета. 4. Качественное выполнение. 5. Сдача работ и гарантия.", "Як ми працюємо, у 5 кроків: 1. Розкажіть, що вам потрібно. 2. Виїзд та оцінка. 3. Письмовий детальний кошторис. 4. Якісне виконання. 5. Здача робіт і гарантія.", "איך אנחנו עובדים, ב-5 שלבים: 1. ספרו לנו מה אתם צריכים. 2. ביקור בשטח והערכה. 3. הצעת מחיר מפורטת בכתב. 4. ביצוע נכון. 5. מסירה ואחריות.", "Cum lucrăm, în 5 pași: 1. Spuneți-ne de ce aveți nevoie. 2. Vizită la fața locului și evaluare. 3. Ofertă scrisă, detaliată. 4. Lucrare făcută corect. 5. Predare și garanție."],
["Built on clear promises: written quotes · licensed technicians · warranty · cleanliness.", "Χτισμένη σε δεσμεύσεις: γραπτές προσφορές · αδειούχοι τεχνικοί · εγγύηση · καθαριότητα.", "Построено на чётких обязательствах: письменные сметы · лицензированные специалисты · гарантия · чистота.", "Побудовано на чітких зобов’язаннях: письмові кошториси · ліцензовані фахівці · гарантія · чистота.", "בנויה על התחייבויות ברורות: הצעות מחיר בכתב · טכנאים מורשים · אחריות · ניקיון.", "Construită pe angajamente clare: oferte scrise · tehnicieni autorizați · garanție · curățenie."],
["Request a quote: Irina, +357 94 091 616 (Russian, Greek, English); Constantin, +357 94 091 613 (Romanian, Greek, English). WhatsApp · Viber · inonda2026@outlook.com · www.inonda.org · Nicosia and all of Cyprus.", "Ζητήστε προσφορά: Irina, +357 94 091 616 (ρωσικά, ελληνικά, αγγλικά)· Constantin, +357 94 091 613 (ρουμανικά, ελληνικά, αγγλικά). WhatsApp · Viber · inonda2026@outlook.com · www.inonda.org · Λευκωσία και όλη η Κύπρος.", "Запросите смету: Irina, +357 94 091 616 (русский, греческий, английский); Constantin, +357 94 091 613 (румынский, греческий, английский). WhatsApp · Viber · inonda2026@outlook.com · www.inonda.org · Никосия и весь Кипр.", "Замовте кошторис: Irina, +357 94 091 616 (російська, грецька, англійська); Constantin, +357 94 091 613 (румунська, грецька, англійська). WhatsApp · Viber · inonda2026@outlook.com · www.inonda.org · Нікосія та весь Кіпр.", "בקשו הצעת מחיר: Irina, ⁦+357 94 091 616⁩ (רוסית, יוונית, אנגלית); Constantin, ⁦+357 94 091 613⁩ (רומנית, יוונית, אנגלית). WhatsApp · Viber · inonda2026@outlook.com · www.inonda.org · ניקוסיה וכל קפריסין.", "Cereți o ofertă: Irina, +357 94 091 616 (rusă, greacă, engleză); Constantin, +357 94 091 613 (română, greacă, engleză). WhatsApp · Viber · inonda2026@outlook.com · www.inonda.org · Nicosia și tot Ciprul."],
['This interactive estimator requires JavaScript. Enable JavaScript to configure a property plan.','Ο διαδραστικός εκτιμητής απαιτεί JavaScript. Ενεργοποιήστε το για να διαμορφώσετε το σχέδιό σας.','Для калькулятора нужен JavaScript. Включите его, чтобы настроить план.','Для калькулятора потрібен JavaScript. Увімкніть його, щоб налаштувати план.','המחשבון דורש JavaScript. הפעילו אותו כדי להגדיר תוכנית לנכס.','Estimatorul necesită JavaScript. Activează-l pentru a configura planul.'],
['validation.number','Το πεδίο «{field}» πρέπει να είναι μεταξύ {min} και {max}.','Поле «{field}» должно быть от {min} до {max}.','Поле «{field}» має бути від {min} до {max}.','הערך בשדה {field} חייב להיות בין {min} ל-{max}.','Câmpul „{field}” trebuie să fie între {min} și {max}.'],
['validation.integer','Το πεδίο «{field}» πρέπει να είναι ακέραιος αριθμός μεταξύ {min} και {max}.','Поле «{field}» должно быть целым числом от {min} до {max}.','Поле «{field}» має бути цілим числом від {min} до {max}.','הערך בשדה {field} חייב להיות מספר שלם בין {min} ל-{max}.','Câmpul „{field}” trebuie să fie un număr întreg între {min} și {max}.']
];
for(const row of details)for(const [i,lang] of ['el','ru','uk','he','ro'].entries())dictionaries[lang][row[0].replace(/\s+/g,' ').trim()]=row[i+1];

const guideTranslations=[["Talk through your plan with Irina on +357 94 091 616 or Constantin on +357 94 091 613. Both contact lines have WhatsApp, Viber and call buttons. You can also email inonda2026@outlook.com. Our team confirms the scope, site assessment and written quote; this guide cannot make a booking.", "Μιλήστε με την Irina στο +357 94 091 616 ή τον Constantin στο +357 94 091 613. Και οι δύο γραμμές έχουν WhatsApp, Viber και κλήση. Email: inonda2026@outlook.com. Η ομάδα επιβεβαιώνει την επιθεώρηση, το αντικείμενο και τη γραπτή προσφορά. Ο οδηγός δεν πραγματοποιεί κρατήσεις.", "Обсудите план с Irina: +357 94 091 616 или Constantin: +357 94 091 613. Для обоих доступны WhatsApp, Viber и звонки. Email: inonda2026@outlook.com. Команда согласует осмотр, объём и письменное предложение. Помощник не оформляет запись.", "Обговоріть план з Irina: +357 94 091 616 або Constantin: +357 94 091 613. Для обох доступні WhatsApp, Viber і дзвінки. Email: inonda2026@outlook.com. Команда узгодить огляд, обсяг і письмову пропозицію. Помічник не оформлює запис.", "דברו על התוכנית עם Irina במספר +357 94 091 616 או Constantin במספר +357 94 091 613. לשניהם כפתורי WhatsApp, Viber ושיחה. דוא״ל: inonda2026@outlook.com. הצוות מאשר את הבדיקה, ההיקף וההצעה הכתובה. המדריך אינו מבצע הזמנות.", "Discută planul cu Irina la +357 94 091 616 sau Constantin la +357 94 091 613. Ambele linii au WhatsApp, Viber și apel. Email: inonda2026@outlook.com. Echipa confirmă inspecția, lucrările și oferta scrisă. Ghidul nu face programări."], ["All displayed service rates, minimum charges, travel allowances and estimate ranges include 19% VAT. The breakdown shows the included VAT separately. It is not added again at the end.", "Όλες οι τιμές υπηρεσιών, ελάχιστες χρεώσεις, μετακινήσεις και εύρη εκτίμησης περιλαμβάνουν 19% ΦΠΑ. Η ανάλυση εμφανίζει ξεχωριστά τον ΦΠΑ που ήδη περιλαμβάνεται. Δεν προστίθεται ξανά στο τέλος.", "Все тарифы, минимальные суммы, проезд и диапазоны включают НДС 19%. В детализации отдельно показан уже включённый НДС. Повторно он не добавляется.", "Усі тарифи, мінімальні суми, проїзд і діапазони включають ПДВ 19%. У деталізації окремо показано вже включений ПДВ. Повторно він не додається.", "כל התעריפים, חיובי המינימום, הנסיעות וטווחי ההערכה כוללים מע״מ 19%. הפירוט מציג בנפרד את המע״מ שכבר כלול. הוא אינו מתווסף שוב בסוף.", "Toate tarifele, minimele, deplasările și intervalele includ TVA 19%. Detalierea arată separat TVA deja inclus. Nu se adaugă din nou la final."], ["INONDA is based at 29 Charalampou Mouskou, 2014 Strovolos, Nicosia, and offers property services across Cyprus. Select your location in the estimator. Contact the team to confirm availability and travel for your property.", "Η INONDA βρίσκεται στη διεύθυνση 29 Charalampou Mouskou, 2014 Strovolos, Λευκωσία και προσφέρει υπηρεσίες ακινήτων σε όλη την Κύπρο. Επιλέξτε τοποθεσία στον εκτιμητή και επικοινωνήστε για διαθεσιμότητα και μετακίνηση.", "INONDA находится по адресу 29 Charalampou Mouskou, 2014 Strovolos, Никосия и оказывает услуги по всему Кипру. Выберите расположение в калькуляторе и уточните у команды доступность и проезд.", "INONDA розташована за адресою 29 Charalampou Mouskou, 2014 Strovolos, Нікосія та надає послуги по всьому Кіпру. Оберіть місце в калькуляторі й уточніть доступність та проїзд.", "INONDA ממוקמת ב-29 Charalampou Mouskou, 2014 Strovolos, ניקוסיה, ומציעה שירותים בכל קפריסין. בחרו מיקום במחשבון ופנו לצוות לאישור זמינות ועלות נסיעה.", "INONDA are sediul la 29 Charalampou Mouskou, 2014 Strovolos, Nicosia și oferă servicii în tot Ciprul. Alege localitatea în estimator și confirmă cu echipa disponibilitatea și deplasarea."], ["Please check the highlighted property or service inputs first. Once they are valid, I can explain your current planning budget.", "Ελέγξτε πρώτα τα επισημασμένα στοιχεία ακινήτου ή υπηρεσιών. Μόλις είναι έγκυρα, μπορώ να εξηγήσω τον τρέχοντα προϋπολογισμό σας.", "Сначала проверьте выделенные данные объекта или услуг. После исправления я смогу объяснить текущий бюджет.", "Спочатку перевірте виділені дані об’єкта або послуг. Після виправлення я зможу пояснити поточний бюджет.", "בדקו תחילה את נתוני הנכס או השירותים המסומנים. לאחר תיקונם אוכל להסביר את התקציב הנוכחי.", "Verifică mai întâi datele evidențiate. După corectare pot explica bugetul curent."], ["Choose one or more services to start your budget. You can mix one-off work with ongoing care and adjust each quantity, rate and minimum charge.", "Επιλέξτε μία ή περισσότερες υπηρεσίες για να ξεκινήσετε. Συνδυάστε εφάπαξ εργασίες με συνεχή φροντίδα και ρυθμίστε ποσότητα, τιμή και ελάχιστη χρέωση.", "Выберите одну или несколько услуг. Можно сочетать разовые работы с постоянным уходом и менять объём, цену и минимум.", "Оберіть одну або кілька послуг. Можна поєднати разові роботи з постійним доглядом і змінити обсяг, ціну та мінімум.", "בחרו שירות אחד או יותר. אפשר לשלב עבודה חד פעמית וטיפול שוטף ולהתאים כמות, תעריף וחיוב מינימום.", "Alege unul sau mai multe servicii. Poți combina lucrări unice cu îngrijire continuă și ajusta cantitatea, tariful și minimul."], ["Choose Residential for an apartment, villa or house, or Commercial for an office, shop or shared facility. The estimator shows the applicable rates and minimums for your selected property type, with 19% VAT included.", "Επιλέξτε Κατοικία για διαμέρισμα, βίλα ή σπίτι και Επαγγελματικό για γραφείο, κατάστημα ή κοινόχρηστο χώρο. Οι εμφανιζόμενες τιμές και τα ελάχιστα αντιστοιχούν στον επιλεγμένο τύπο και περιλαμβάνουν 19% ΦΠΑ.", "Выберите жилой объект для квартиры, виллы или дома, коммерческий — для офиса, магазина или общего пространства. Цены и минимумы соответствуют выбранному типу и включают НДС 19%.", "Оберіть житловий об’єкт для квартири, вілли або будинку, комерційний — для офісу, магазину чи спільного простору. Ціни й мінімуми відповідають типу та включають ПДВ 19%.", "בחרו מגורים לדירה, וילה או בית, ומסחרי למשרד, חנות או שטח משותף. התעריפים והמינימום מתאימים לסוג הנבחר וכוללים מע״מ 19%.", "Alege Rezidențial pentru apartament, vilă sau casă și Comercial pentru birou, magazin sau spațiu comun. Tarifele și minimele corespund tipului și includ TVA 19%."], ["Choose routine, deep or move-in / move-out cleaning. Set the indoor area and choose a one-off visit or ongoing frequency. Routine labour and basic consumables are assumed; specialist machinery, hazardous materials and waste removal need separate agreement.", "Επιλέξτε τακτικό, βαθύ καθαρισμό ή καθαρισμό εισόδου/αποχώρησης. Ορίστε εσωτερικό εμβαδόν και συχνότητα. Προβλέπονται συνήθης εργασία και βασικά αναλώσιμα. Ειδικός εξοπλισμός, επικίνδυνα υλικά και απομάκρυνση αποβλήτων συμφωνούνται χωριστά.", "Выберите регулярную, генеральную уборку или уборку при въезде/выезде. Задайте площадь и частоту. Учтены обычный труд и базовые расходники; спецтехника, опасные материалы и вывоз отходов согласуются отдельно.", "Оберіть регулярне, генеральне прибирання або прибирання при заселенні/виїзді. Задайте площу й частоту. Враховано звичайну працю та базові витратні матеріали; спецтехніка, небезпечні матеріали й вивезення відходів узгоджуються окремо.", "בחרו ניקיון שוטף, יסודי או לפני כניסה/לאחר עזיבה. הגדירו שטח ותדירות. כלולים עבודה רגילה וחומרים בסיסיים. ציוד מיוחד, חומרים מסוכנים ופינוי פסולת דורשים הסכמה נפרדת.", "Alege curățenie periodică, generală sau la mutare/eliberare. Setează suprafața și frecvența. Sunt incluse manopera obișnuită și consumabilele de bază; utilajele speciale, materialele periculoase și deșeurile se stabilesc separat."], ["Renovation lets you explore a cosmetic refresh, partial refurbishment or full finish refurbishment for a selected area. The allowance covers the selected labour and basic finishes. Structural work, permits, fixtures and major plumbing or electrical works need a separate assessment.", "Η ανακαίνιση προσφέρει αισθητική ανανέωση, μερική ή πλήρη ανακαίνιση τελειωμάτων για επιλεγμένο εμβαδόν. Περιλαμβάνει επιλεγμένη εργασία και βασικά τελειώματα. Δομικά έργα, άδειες, εξαρτήματα και μεγάλα υδραυλικά/ηλεκτρολογικά απαιτούν ξεχωριστή αξιολόγηση.", "Ремонт позволяет выбрать косметическое, частичное или полное обновление отделки. Учтены выбранная работа и базовые отделочные материалы. Конструкции, разрешения, оборудование и крупные инженерные работы требуют отдельной оценки.", "Ремонт дозволяє обрати косметичне, часткове або повне оновлення оздоблення. Враховано обрану роботу й базові матеріали. Конструкції, дозволи, обладнання та великі інженерні роботи потребують окремої оцінки.", "השיפוץ מאפשר רענון קוסמטי, שיפוץ חלקי או חידוש גמרים מלא לשטח נבחר. כלולים העבודה והגמרים הבסיסיים שנבחרו. מבנה, היתרים, אביזרים ועבודות אינסטלציה וחשמל גדולות דורשים בדיקה נפרדת.", "Renovarea permite reîmprospătare cosmetică, renovare parțială sau completă a finisajelor. Include manopera și finisajele de bază selectate. Structura, autorizațiile, dotările și instalațiile majore necesită evaluare separată."], ["The management allowance covers monthly service coordination and reporting per managed unit. Third-party bills and rent collection are excluded from this estimator. Contact INONDA to discuss the management arrangement you need.", "Η διαχείριση καλύπτει μηνιαίο συντονισμό υπηρεσιών και αναφορές ανά μονάδα. Δεν περιλαμβάνει λογαριασμούς τρίτων ή είσπραξη ενοικίων. Συζητήστε με την INONDA τη συμφωνία διαχείρισης που χρειάζεστε.", "Управление включает ежемесячную координацию и отчётность по объекту. Счета третьих лиц и сбор аренды исключены. Обсудите нужную схему с INONDA.", "Управління включає щомісячну координацію та звітність за об’єктом. Рахунки третіх осіб і збір оренди виключено. Обговоріть потрібну схему з INONDA.", "הניהול כולל תיאום שירותים ודיווח חודשי לכל יחידה. חשבונות צד שלישי וגביית שכירות אינם כלולים. פנו ל-INONDA לדיון בהסדר הניהול המתאים.", "Administrarea include coordonare și raportare lunară per unitate. Facturile terților și colectarea chiriei sunt excluse. Discută cu INONDA aranjamentul potrivit."], ["Landscaping covers a routine garden tidy for the outdoor area you enter. You can set one-off or recurring visits. Landscape construction, tall trees, specialist machinery and waste removal need separate agreement.", "Η κηποτεχνία καλύπτει τακτική περιποίηση στο εξωτερικό εμβαδόν που εισάγετε, εφάπαξ ή επαναλαμβανόμενα. Κατασκευές κήπου, ψηλά δέντρα, ειδικός εξοπλισμός και απομάκρυνση αποβλήτων συμφωνούνται χωριστά.", "Уход за садом включает обычную уборку выбранной площади разово или регулярно. Строительство, высокие деревья, спецтехника и вывоз отходов согласуются отдельно.", "Догляд за садом включає звичайне прибирання обраної площі разово або регулярно. Будівництво, високі дерева, спецтехніка й вивезення відходів узгоджуються окремо.", "הגינון כולל סידור שוטף של שטח החוץ שהזנתם, חד פעמי או קבוע. בניית גן, עצים גבוהים, ציוד מיוחד ופינוי פסולת דורשים הסכמה נפרדת.", "Grădinăritul include îngrijire obișnuită pentru suprafața introdusă, o dată sau recurent. Construcțiile, arborii înalți, utilajele speciale și evacuarea deșeurilor se stabilesc separat."], ["Maintenance provides a preventive inspection allowance; handyman provides an hourly labour allowance for small jobs. Parts, repairs and specialist trades are excluded from those allowances. Plumbing and electrical work should be discussed with the team so the right professional can assess it.", "Η συντήρηση προβλέπει προληπτική επιθεώρηση και οι μικροεπισκευές ωριαία εργασία. Δεν περιλαμβάνονται ανταλλακτικά, επισκευές συντήρησης ή εξειδικευμένα επαγγέλματα. Συζητήστε υδραυλικά και ηλεκτρολογικά με την ομάδα για τον κατάλληλο αδειούχο επαγγελματία.", "Обслуживание — это профилактический осмотр, мелкий ремонт — почасовой труд мастера. Детали и специальные работы не включены. Сантехнику и электрику обсудите с командой для осмотра нужным специалистом.", "Обслуговування — це профілактичний огляд, дрібний ремонт — погодинна праця майстра. Деталі та спеціальні роботи не включено. Сантехніку й електрику обговоріть із командою для огляду потрібним фахівцем.", "תחזוקה היא אומדן לבדיקה מונעת, ותיקונים קטנים הם אומדן עבודה לפי שעה. חלקים ועבודות מומחים אינם כלולים. שוחחו עם הצוות על אינסטלציה וחשמל כדי להפנות לבעל המקצוע המתאים.", "Întreținerea reprezintă o inspecție preventivă, iar reparațiile mici sunt calculate pe oră. Piesele și lucrările specializate nu sunt incluse. Discută cu echipa despre instalații și electricitate pentru evaluarea de către specialistul potrivit."], ["Save up to three scenarios in your browser to compare plans. “Download my plan” includes your selected services, quantities, rates, VAT and exclusions. You can also print or save as PDF, then share your plan with INONDA when you contact the team.", "Αποθηκεύστε έως τρία σενάρια στον φυλλομετρητή για σύγκριση. Η λήψη σχεδίου περιλαμβάνει υπηρεσίες, ποσότητες, τιμές, ΦΠΑ και εξαιρέσεις. Μπορείτε επίσης να εκτυπώσετε ή να αποθηκεύσετε PDF και να μοιραστείτε το σχέδιο με την INONDA.", "Сохраните до трёх вариантов в браузере. Скачанный план включает услуги, объёмы, цены, НДС и исключения. Можно распечатать или сохранить PDF и передать INONDA.", "Збережіть до трьох варіантів у браузері. Завантажений план містить послуги, обсяги, ціни, ПДВ і винятки. Можна роздрукувати або зберегти PDF та передати INONDA.", "שמרו עד שלושה תרחישים בדפדפן להשוואה. התוכנית להורדה כוללת שירותים, כמויות, תעריפים, מע״מ והחרגות. אפשר גם להדפיס או לשמור PDF ולשתף עם INONDA.", "Salvează până la trei scenarii în browser. Planul descărcat include servicii, cantități, tarife, TVA și excluderi. Poți tipări sau salva PDF și trimite planul către INONDA."], ["One-off work and ongoing monthly costs are shown separately. Weekly visits average 52 ÷ 12 visits per month. You can change the visit frequency for cleaning, handyman and landscaping; management is monthly.", "Οι εφάπαξ εργασίες και τα συνεχή μηνιαία κόστη εμφανίζονται ξεχωριστά. Οι εβδομαδιαίες επισκέψεις υπολογίζονται κατά μέσο όρο ως 52 ÷ 12 τον μήνα. Ρυθμίστε τη συχνότητα για καθαρισμό, μικροεπισκευές και κηποτεχνία· η διαχείριση είναι μηνιαία.", "Разовые и месячные расходы показаны отдельно. Еженедельные визиты в среднем равны 52 ÷ 12 в месяц. Частоту можно менять для уборки, мелкого ремонта и сада; управление ежемесячное.", "Разові й місячні витрати показано окремо. Щотижневі візити в середньому дорівнюють 52 ÷ 12 на місяць. Частоту можна змінювати для прибирання, дрібного ремонту й саду; управління щомісячне.", "עבודות חד פעמיות ועלויות חודשיות מוצגות בנפרד. ביקורים שבועיים מחושבים כ-52 ÷ 12 לחודש בממוצע. אפשר לשנות תדירות לניקיון, תיקונים וגינון; הניהול חודשי.", "Lucrările unice și costurile lunare sunt separate. Vizitele săptămânale sunt în medie 52 ÷ 12 pe lună. Poți schimba frecvența la curățenie, reparații mici și grădinărit; administrarea este lunară."], ["Start with your property type, location and size. Select the services you need, then adjust the quantities, rates and frequency. Your estimate updates instantly, including 19% VAT. I can help with services, scope, budgets, saved plans and contacting the team. For anything specific to your property, speak with INONDA.", "Ξεκινήστε με τύπο ακινήτου, τοποθεσία και εμβαδόν. Επιλέξτε υπηρεσίες και ρυθμίστε ποσότητες, τιμές και συχνότητα. Η εκτίμηση ενημερώνεται άμεσα με 19% ΦΠΑ. Μπορώ να βοηθήσω με υπηρεσίες, προϋπολογισμό, αποθήκευση και επικοινωνία. Για ειδικές ανάγκες μιλήστε με την INONDA.", "Начните с типа объекта, места и площади. Выберите услуги, объёмы, цены и частоту. Расчёт обновляется сразу с НДС 19%. Я помогу с услугами, бюджетом, сохранением и контактами. Особенности объекта обсудите с INONDA.", "Почніть із типу об’єкта, місця та площі. Оберіть послуги, обсяги, ціни й частоту. Розрахунок оновлюється одразу з ПДВ 19%. Я допоможу з послугами, бюджетом, збереженням і контактами. Особливості об’єкта обговоріть з INONDA.", "התחילו בסוג הנכס, המיקום והשטח. בחרו שירותים והתאימו כמויות, תעריפים ותדירות. ההערכה מתעדכנת מיד עם מע״מ 19%. אוכל לעזור בשירותים, תקציב, שמירה ויצירת קשר. לצרכים מיוחדים פנו ל-INONDA.", "Începe cu tipul proprietății, localitatea și suprafața. Alege servicii, cantități, tarife și frecvență. Estimarea se actualizează imediat cu TVA 19%. Pot ajuta cu servicii, buget, salvare și contact. Pentru detalii specifice discută cu INONDA."]];
for(const row of guideTranslations)for(const [i,lang] of ['el','ru','uk','he','ro'].entries())dictionaries[lang][row[0].replace(/\s+/g,' ').trim()]=row[i+1];
